import{R as t,e as o,f as i,U as n}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Microsoft Dynamics 365","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/microsoft-dynamics-365.md","filePath":"integrations/crm/microsoft-dynamics-365.md","lastUpdated":1775908585000}'),r={name:"integrations/crm/microsoft-dynamics-365.md"};function s(a,e,l,c,h,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="microsoft-dynamics-365" tabindex="-1">Microsoft Dynamics 365 <a class="header-anchor" href="#microsoft-dynamics-365" aria-label="Permalink to &quot;Microsoft Dynamics 365&quot;">​</a></h1><p>Follow the below steps to connect to the Microsoft Dynamics 365 API.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Ensure you have Azure administrator access or an Azure administrator is able to grant permissions to the application. This is required to approve the application in Microsoft Dynamics 365.</p></div><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Microsoft Dynamics 365 as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-microsoft-dynamics-365-api" tabindex="-1">Step 2. Connect to the Microsoft Dynamics 365 API <a class="header-anchor" href="#step-2-connect-to-the-microsoft-dynamics-365-api" aria-label="Permalink to &quot;Step 2. Connect to the Microsoft Dynamics 365 API&quot;">​</a></h3><ol><li>Go to <a href="https://aad.portal.azure.com/" target="_blank">Azure Active Directory Admin Center</a> and login to your account.</li><li>Click on the <strong>Azure Active Directory</strong> in the left-hand sidebar, <strong>App Registrations</strong> then <strong>New Registration</strong>. <ul><li>Under <strong>Supported account types</strong> select <strong>Accounts in any organizational directory (Any Azure AD directory - Multitenant) and personal Microsoft accounts (e.g. Skype, Xbox)</strong>.</li><li>In the <strong>Redirect URI</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Click the <strong>Register</strong> button.</li></ul></li><li>Copy the <strong>Application (client) ID</strong> from Microsoft Dynamics 365 and paste in the <strong>Client ID</strong> field in Formie.</li><li>Click on the <strong>Certificates &amp; Secrets</strong> in the left-hand sidebar.</li><li>Click the <strong>New client secret</strong> button and provide a name and appropriate expiry.</li><li>Copy the <strong>Value</strong> from Microsoft Dynamics 365 for the resulting secret and paste in the <strong>Client Secret</strong> field below.</li><li>Click on the <strong>API Permissions</strong> in the left-hand sidebar.</li><li>Click the <strong>Add a Permission</strong> button.</li><li>Select <strong>Microsoft Graph</strong>, then the <strong>Delegated permissions</strong> option and select the following permissions: <ul><li><code>email</code></li><li><code>offline_access</code></li><li><code>openid</code></li><li><code>profile</code></li></ul></li><li>Click <strong>Add Permissions</strong>.</li><li>Navigate back to <strong>All APIs</strong> and select <strong>Dynamics CRM</strong> and select the following permissions: <ul><li><code>user_impersonation</code></li></ul></li><li>Click <strong>Add Permissions</strong>.</li><li>Navigate back to <strong>API Permissions</strong> and click the <strong>Grant Admin Consent</strong> button, and agree to the prompt.</li></ol><h3 id="step-3-create-an-application-user" tabindex="-1">Step 3. Create an Application User <a class="header-anchor" href="#step-3-create-an-application-user" aria-label="Permalink to &quot;Step 3. Create an Application User&quot;">​</a></h3><ol><li>Go to <a href="https://admin.powerplatform.microsoft.com/" target="_blank">Power Platform Admin Center</a> and login to your account as a System Administrator.</li><li>Click <strong>Environments</strong> in the left-hand sidebar, and then select an environment from the list.</li><li>Copy the <strong>Environment URL</strong> from Power Platform and paste in the <strong>Domain</strong> field in Formie. Be sure to include the <code>https://</code> (e.g. <code>https://ffcor.crm6.dynamics.com</code>).</li><li>Click the <strong>Settings</strong> button in the top navigation.</li><li>Click <strong>Users + Permissions</strong>, and then click <strong>Application Users</strong>.</li><li>Click the <strong>+ New app user</strong> button in the top navigation.</li><li>Click <strong>+ Add an app</strong> to choose the registered Azure AD application that was created for the selected user, and then click the <strong>Add</strong> button.</li><li>Select a business unit from the dropdown list for <strong>Business Unit</strong>.</li><li>Click <strong>Security roles</strong> and add the following: <ul><li><code>Basic User</code></li></ul></li><li>Click the <strong>Save</strong> button, then the <strong>Create</strong> button.</li></ol><h3 id="step-4-test-connection" tabindex="-1">Step 4. Test Connection <a class="header-anchor" href="#step-4-test-connection" aria-label="Permalink to &quot;Step 4. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Microsoft Dynamics 365, where you must approve Formie to access your Microsoft Dynamics 365 account.</li></ol><h3 id="step-5-form-setting" tabindex="-1">Step 5. Form Setting <a class="header-anchor" href="#step-5-form-setting" aria-label="Permalink to &quot;Step 5. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="optional-web-api-version" tabindex="-1">Optional: Web API version <a class="header-anchor" href="#optional-web-api-version" aria-label="Permalink to &quot;Optional: Web API version&quot;">​</a></h3><p>The Microsoft Dynamics 365 Web API provides <a href="https://learn.microsoft.com/en-us/power-apps/developer/data-platform/webapi/web-api-versions" target="_blank" rel="noreferrer">different versions of the Web API</a>. This is to both maintain compatibility or implement new breaking changes. There are no major differences between v9.0, v9.1 or v9.2 currently. This setting allows you to specify a specific API version if required. When setting a specific value, all Microsoft Dynamics 365 Web API requests will use this API version in the request URI.</p><p>For compatibility, the default setting is v9.0. This has been the value used in the Microsoft Dynamics 365 CRM integration prior to this being customisable.</p><h3 id="optional-impersonate-user" tabindex="-1">Optional: Impersonate user <a class="header-anchor" href="#optional-impersonate-user" aria-label="Permalink to &quot;Optional: Impersonate user&quot;">​</a></h3><p>When CRM records are created through Formie the user context of the account used to authenticate the OAuth connection is used (this is different to the application user). Depending on requirements, you may wish to override this. The easiest option is to authenticate under the account you wish to have records created by as, however this may not always be possible.</p><p>Using <a href="https://learn.microsoft.com/en-us/power-apps/developer/data-platform/webapi/impersonate-another-user-web-api#how-to-impersonate-a-user" target="_blank">user impersonation</a> you can set another systemuser context instead without changing the OAuth connection.</p><p><strong>Impersonation settings:</strong></p><ul><li>Impersonate user - Toggle the entire feature on or off.</li><li>Impersonate header - This sets the HTTP header to either <code>CallerObjectId</code> or <code>MSCRMCallerID</code>. Depending on your environment one or the other will need to be used relative to the user ID provided.</li><li>Impersonate User ID - This is the GUID of a valid systemuser within your Microsoft Dynamics 365 CRM.</li></ul><p>When enabled this will be applied to all Microsoft Dynamics 365 CRM enabled forms.</p><p>By setting the impersonate HTTP header, this will also populate the Created By (delegate) field to the actual user context to provide a more accurate audit trail.</p><p>If you want to selectively control the &quot;Created&quot; By value on records per form, use the Created By field in the mapping.</p><p><strong>Note:</strong> The impersonate user feature is set via a HTTP header on POST requests which will override any Created By field mapping that is set.</p>',25)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
